Lemma musl_tls_get_addr_run : forall regs (M rom : word -> option byte) (ret : word) (d tpv md off dtv ent : Z),
  getr regs 10 = Z_to_bv 64 d -> getr regs 4 = Z_to_bv 64 tpv -> getr regs 1 = ret -> ret_ok ret ->
